var lang = "";
function language() {
    if (lang == "") {
        lang = ("" + helper.language).substring(0, 2).toLowerCase()
        if (lang == "") lang = "en"
    }
    return lang
}

// t("text", a1, a2): translation with %1 and %2 replaced.
function t(s, a1, a2) {
    var r = s
    var e = dict[s]
    if (e !== undefined && e[language()] !== undefined)
        r = e[language()]
    if (a1 !== undefined) r = r.replace("%1", a1)
    if (a2 !== undefined) r = r.replace("%2", a2)
    return r
}
